    private trimReportedLoadErrorKeys() {
        while (this.reportedLoadErrorKeys.size > MAX_REPORTED_LOAD_ERROR_KEYS) {
            const [oldestKey] = this.reportedLoadErrorKeys

            this.reportedLoadErrorKeys.delete(oldestKey)
        }
    }

    private async runStateAction(action: ActionDefinition, context: ActionContext, cardInternalId: string | null) {
        try {
            const result = await runElectronAction(action, context, {}, undefined, false)
            if (result.status === 'completed') return

            const failedLog = result.logs.find((log) => log.status === 'failed')
            this.recordCardAgentError(cardInternalId, action.id, failedLog?.message ?? `${action.label} failed`)
        } catch (error) {
            this.recordCardAgentError(cardInternalId, action.id, error instanceof Error ? error.message : `${action.label} failed`)
        }
    }

    /** A card without an internal ID has nowhere to attach the failure, so it only reaches telemetry. */
    private recordCardAgentError(cardInternalId: string | null, actionId: string, message: string) {
        if (!cardInternalId) {
            telemetryService.captureError(new Error(`${actionId}: ${message}`))
            return
        }

        const error: AgentConversationError = { kind: 'onStateAction', message, path: actionId }
        this.errorsByCardInternalId.set(cardInternalId, [...(this.errorsByCardInternalId.get(cardInternalId) ?? []), error])
        this.notifyConversationsChanged(cardInternalId)
    }

    /** Notifies through the card's current path, which a rename or an archive may have changed meanwhile. */
    private notifyConversationsChanged(cardInternalId: string) {
        const card = this.dependencies.findCardByInternalId(cardInternalId)
        if (card) this.dependencies.conversationsChanged(card.path)
    }

    private handleActionRunEvent(event: ActionRunEvent) {
        if (
            event.type === 'update'
            && (event.update.kind === 'agentStarted' || event.update.kind === 'agentClosed')
            && !event.context.cardInternalId
        ) {
            this.upsertProjectConversation(event.update.conversation)
            return
        }

        if (
            event.type === 'update'
            && (event.update.kind === 'agentStarted' || event.update.kind === 'agentClosed')
            && event.context.cardInternalId
        ) {
            this.upsertAgentConversation(event.context.cardInternalId, event.update.conversation)
        }
    }

    private updateProjectConversation(conversation: AgentConversation) {
        if (!this.projectConversations.some(({ id }) => id === conversation.id)) return

        this.projectConversations = this.projectConversations.map((current) => (
            current.id === conversation.id ? conversation : current
        ))
        agentAcknowledgementService.announceConversationsChanged(null, [])
    }

    private upsertProjectConversation(conversation: AgentConversation) {
        this.projectConversations = this.projectConversations.some(({ id }) => id === conversation.id)
            ? this.projectConversations.map((current) => current.id === conversation.id ? conversation : current)
            : [...this.projectConversations, conversation]
        agentAcknowledgementService.announceConversationsChanged(null, [])
    }

    private upsertAgentConversation(cardInternalId: string, conversation: AgentConversation) {
        const conversations = this.conversationsByCardInternalId.get(cardInternalId) ?? []
        const nextConversations = conversations.some((current) => current.id === conversation.id)
            ? conversations.map((current) => (current.id === conversation.id ? conversation : current))
            : [...conversations, conversation]
        this.conversationsByCardInternalId.set(cardInternalId, nextConversations)
        this.notifyConversationsChanged(cardInternalId)
        const actionIds = conversation.actionId ? [conversation.actionId] : []
        agentAcknowledgementService.announceConversationsChanged(cardInternalId, actionIds)
    }
}

import type { ActionRunEvent, ActionRunStatus } from '../../data/action_run_types'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import type { AgentConversation } from '../../data/data_types'
import { actionRunRegistry } from '../actions/action_run_registry'
import { dialogService } from '../dialog_service'
import { register } from '../service_injector'

const UNSEEN_STATUSES = new Set<ActionRunStatus>(['completed', 'failed', 'waitingForInput'])
const PROJECT_SCOPE_KEY = 'project'

type ResolveStoredConversation = (conversation: AgentConversation) => AgentConversation | null
export type AgentConversationScope = string | null

/** Event type dispatched for aggregate acknowledgement changes on one card. */
export function cardAcknowledgementEvent(cardInternalId: string) {
    return `card-${cardInternalId}`
}

/** Event type dispatched for acknowledgement changes on one card action. */
export function actionAcknowledgementEvent(cardInternalId: string, actionId: string) {
    return `action-${cardInternalId}-${actionId}`
}

/** Event type dispatched for project-origin conversation changes. */
export const PROJECT_ACKNOWLEDGEMENT_EVENT = 'project-conversations'

function conversationKey(scope: AgentConversationScope, actionId: string, conversationId: string) {
    return `${scope ?? PROJECT_SCOPE_KEY}-${actionId}-${conversationId}`
}

async function persistConversationViewed(reference: string, viewed: boolean) {
    const bridge = getElectronActionBridge()
    if (!bridge?.updateActionConversationViewed) throw new Error('Updating conversation view state requires Electron')

    return bridge.updateActionConversationViewed(reference, viewed)
}

/**
 * Tracks chat visibility and persists conversation view state.
 * Changes are announced through scoped card and card-action events so only affected leaves update;
 * the conversation data itself lives in the agent integration store and the activity files.
 * Scoping uses the stable card internal ID so card renames cannot break acknowledgement state.
 */
export class AgentAcknowledgementService extends EventTarget {
    private readonly lastRunStatuses = new Map<string, ActionRunStatus>()
    private resolveStoredConversation: ResolveStoredConversation | null = null
    private readonly visibleEntries = new Map<string, Set<string>>()

    constructor() {
        super()
        actionRunRegistry.subscribeActiveRunEvents(this.handleActionRunEvent)
    }

    /** Connects the loaded-conversation store so view changes land on the canonical conversation records. */
    connectConversationStore(resolveStoredConversation: ResolveStoredConversation) {
        this.resolveStoredConversation = resolveStoredConversation
    }

    /** Announce acknowledgement-relevant conversation changes to the scoped card and card-action subscribers. */
    announceConversationsChanged(scope: AgentConversationScope, actionIds: string[]) {
        if (scope === null) {
            this.dispatchEvent(new Event(PROJECT_ACKNOWLEDGEMENT_EVENT))
            return
        }

        for (const actionId of new Set(actionIds)) {
            this.dispatchEvent(new Event(actionAcknowledgementEvent(scope, actionId)))
        }
        this.dispatchEvent(new Event(cardAcknowledgementEvent(scope)))
    }

    setConversationVisible(
        entryId: string,
        scope: AgentConversationScope,
        actionId: string,
        conversation: AgentConversation,
        visible: boolean,
    ) {
        const key = conversationKey(scope, actionId, conversation.id)
        const entries = this.visibleEntries.get(key) ?? new Set<string>()
        if (visible) entries.add(entryId)
        else entries.delete(entryId)
        if (entries.size > 0) this.visibleEntries.set(key, entries)
        else this.visibleEntries.delete(key)
        const current = this.resolveStoredConversation?.(conversation) ?? conversation
        if (visible && !current.viewed) {
            void this.setViewed(scope, actionId, conversation, true).catch(() => undefined)
        }
    }

    async setViewed(scope: AgentConversationScope, actionId: string, conversation: AgentConversation, viewed: boolean) {
        const current = this.resolveStoredConversation?.(conversation) ?? conversation
        if (current.viewed === viewed) return current

        try {
            await persistConversationViewed(conversation.path, viewed)
        } catch (error) {
            const fallbackMessage = scope === null
                ? 'Project conversation view state could not be saved'
                : 'Card conversation view state could not be saved'
            dialogService.error(error, { fallbackMessage })
            throw error
        }
        current.viewed = viewed
        conversation.viewed = viewed
        this.announceConversationsChanged(scope, [actionId])

        return current
    }

    /** Clears transient state at a project boundary. */
    reset() {
        this.lastRunStatuses.clear()
        this.visibleEntries.clear()
    }

    private readonly handleActionRunEvent = (event: ActionRunEvent) => {
        const previousStatus = this.lastRunStatuses.get(event.runId)
        this.lastRunStatuses.set(event.runId, event.status)
        if (previousStatus === event.status || !UNSEEN_STATUSES.has(event.status)) return

        const conversation = actionRunRegistry.getRunStore(event.runId)?.getSnapshot().conversation ?? null
        const scope = event.context.cardInternalId ?? null
        const actionId = conversation?.actionId
        if (!conversation || !actionId) return
        if ((this.visibleEntries.get(conversationKey(scope, actionId, conversation.id))?.size ?? 0) > 0) return

        void this.setViewed(scope, actionId, conversation, false).catch(() => undefined)
    }

}

export const agentAcknowledgementService = register('agentAcknowledgementService', new AgentAcknowledgementService())

import type { ActionContext } from './action_context'
import type {
    AgentContextWindowUsage,
    AgentConversation,
    AgentQuestion,
    AgentConversationEventEntry,
    AgentConversationMessageEntry,
    AgentConversationTimer,
    AgentTokenUsage,
} from './data_types'
import type { PermissionMode, ThinkingLevel } from './agent_profiles'
import type { ActionAutoFinish, ActionOutput, ActionType } from './action_types'

export type ActionRunTerminalStatus = 'cancelled' | 'completed' | 'failed' | 'okButNotAfter'
export type ActionRunStatus = ActionRunTerminalStatus | 'queued' | 'running' | 'waitingForInput'
export type ActionRunPhase = 'after' | 'before' | 'main' | 'on'

export interface ActionRunInput {
    agent?: string
    command?: string
    continueFrom?: string
    diagramPath?: string
    extraPrompt?: string
    model?: string
    permissionMode?: PermissionMode
    prompt?: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionPromptRequest {
    actionId: string
    context: ActionContext
}

export interface PreparedActionPrompt {
    diagramPath?: string
    prompt: string
}

export interface ActionQueuedPrompt {
    content: string
    dispatchState: 'dispatching' | 'queued'
    id: string
    revision: number
}

export interface AgentConversationReservation {
    activityPath: string
    conversationId: string
    reference: string
}

export interface ActionStartRequest {
    actionId: string
    conversationReservation?: AgentConversationReservation
    context: ActionContext
    runInput: ActionRunInput
}

export type { AgentQuestion, AgentQuestionOption } from './data_types'

export type AgentApprovalRequestId = number | string
export type AgentNetworkProtocol = 'http' | 'https' | 'socks5Tcp' | 'socks5Udp'
export type AgentFileSystemPath =
    | { path: string, type: 'path' }
    | { pattern: string, type: 'glob_pattern' }
    | { type: 'special', value: string }
export interface AgentAdditionalPermissions {
    fileSystem: {
        entries?: { access: 'deny' | 'read' | 'write', path: AgentFileSystemPath }[]
        read: string[] | null
        write: string[] | null
    } | null
    network: { enabled: boolean | null } | null
}
export type AgentCommandAction =
    | { command: string, name: string, path: string, type: 'read' }
    | { command: string, path: string | null, type: 'listFiles' }
    | { command: string, path: string | null, query: string | null, type: 'search' }
    | { command: string, type: 'unknown' }
export interface AgentNetworkPolicyAmendment {
    action: 'allow' | 'deny'
    host: string
}
export type AgentApprovalDecision =
    | 'accept'
    | 'acceptForSession'
    | 'cancel'
    | 'decline'
    | { acceptWithExecpolicyAmendment: { execpolicy_amendment: string[] } }
    | { applyNetworkPolicyAmendment: { network_policy_amendment: AgentNetworkPolicyAmendment } }
export interface AgentApproval {
    additionalPermissions?: AgentAdditionalPermissions | null
    approvalId?: string | null
    availableDecisions?: AgentApprovalDecision[] | null
    command?: string | null
    commandActions?: AgentCommandAction[] | null
    cwd?: string | null
    environmentId?: string | null
    filePaths: string[]
    grantRoot?: string | null
    input?: Record<string, unknown> | null
    itemId: string
    kind: 'commandExecution' | 'fileChange' | 'toolUse'
    networkApprovalContext?: { host: string, protocol: AgentNetworkProtocol } | null
    parentItemId?: string | null
    proposedExecpolicyAmendment?: string[] | null
    proposedNetworkPolicyAmendments?: AgentNetworkPolicyAmendment[] | null
    provider?: 'claude' | 'codex'
    permissionSuggestions?: unknown[] | null
    reason?: string | null
    requestId: AgentApprovalRequestId
    startedAtMs: number
    subAgentLabel?: string | null
    threadId?: string
    toolName?: string | null
    turnId?: string
}

interface ActionRunEventBase {
    actionId: string
    actionType?: ActionType
    autoFinish?: ActionAutoFinish | null
    changedPaths?: string[]
    context: ActionContext
    diagramPath?: string
    runId: string
    interactionReady?: boolean
    output?: ActionOutput | null
    phase: ActionRunPhase
    rootActionId: string
    sequence?: number
    streaming?: boolean
}

export type ActionRunUpdate =
    | {
        continued?: boolean
        conversation: AgentConversation
        kind: 'agentStarted'
    }
    | {
        conversation: AgentConversation
        kind: 'agentClosed'
    }
    | {
        kind: 'agentQuestion'
        questions: AgentQuestion[]
        requestId: number | string | null
    }
    | {
        event: AgentConversationEventEntry
        kind: 'agentQuestionDismissed'
        requestId: number | string | null
    }
    | {
        approval: AgentApproval
        kind: 'agentApproval'
    }
    | {
        kind: 'agentApprovalResolved' | 'agentApprovalSubmitted'
        requestId: AgentApprovalRequestId
    }
    | {
        kind: 'agentQuestionAnswer'
        requestId: number | string | null
        userMessage: AgentConversationMessageEntry
    }
    | {
        kind: 'agentUserMessage'
        userMessage: AgentConversationMessageEntry
    }
    | {
        entryIndex: number
        event: AgentConversationEventEntry
        kind: 'agentEvent'
    }
    | {
        contextWindowUsage?: AgentContextWindowUsage | null
        kind: 'agentUsage'
        usage: AgentTokenUsage
    }
    | {
        entry: ActionQueuedPrompt
        kind: 'agentPromptQueued' | 'agentPromptEdited'
    }
    | {
        kind: 'agentPromptRemoved'
        promptId: string
        revision: number
    }
    | {
        command?: string
        content: string
        kind: 'error' | 'output'
    }
    | {
        content: string
        entryIndex: number
        kind: 'agentOutput'
        messageId: string
        previousContent?: string
        replace?: boolean
        sequence: number
    }

export type ActionRunEvent =
    | ActionRunEventBase & {
        status: ActionRunStatus
        type: 'run'
    }
    | ActionRunEventBase & {
        command?: string
        conversationId?: string
        runWorktree?: number | null
        message?: string | null
        permissionMode?: PermissionMode
        reference?: string
        status: ActionRunStatus
        thinkingLevel?: ThinkingLevel
        type: 'action'
    }
    | ActionRunEventBase & {
        status: 'running' | 'waitingForInput'
        timer?: AgentConversationTimer
        type: 'agentState'
    }
    | ActionRunEventBase & {
        status: ActionRunStatus
        /** Present on `agentEvent` updates so a long uninterrupted run keeps the timer breakdown fresh. */
        timer?: AgentConversationTimer
        type: 'update'
        update: ActionRunUpdate
    }

export interface ActionRunLogEntry {
    actionId: string
    actionName: string
